50	// Does `cmd` resolve to an executable (absolute/relative path, or via PATH)?
51	bool cmd_exists(const std::string& cmd) {
52	  if (cmd.find('/') != std::string::npos)
53	    return ::access(cmd.c_str(), X_OK) == 0;
54	  const char* path_env = std::getenv("PATH");
55	  if (!path_env) return false;
56	  std::istringstream ss(path_env);
57	  std::string dir;
58	  while (std::getline(ss, dir, ':'))
59	    if (!dir.empty() && ::access((dir + "/" + cmd).c_str(), X_OK) == 0)
60	      return true;
61	  return false;
62	}
